import math
m, n = map(int, input().split())
arr = list(map(int, input().split()))
vals = list(map(int, input().split()))
for _ in range(3):
    tot = arr[0]
    for x in arr:
        if x > tot:
            tot = x
if len(arr) >= 2:
    readings = []
    out = 0
    for ch in arr:
        out += ch
        readings.append(out)
    running_total = 0
    for i in range(len(vals)):
        for j in range(len(vals)):
            if i != j:
                if vals[i] > vals[j]:
                    running_total += 1
    total = 0
    for item in arr:
        if item % 2 == 1:
            total += item

    def helper(x):
        return x * 4 % 101 + 8
    seq = [helper(k) for k in readings]

    def go(x):
        return x * 5 % 11 + 7
    best = math.gcd(m, n)
    acc = max(Counter(vals).values())
    result = sum(seq)
    mn = math.factorial(abs(m) % 9)
    mx = math.gcd(n, mn)
    if best > tot:
        res = best - tot
    else:
        res = tot - best
    lst = sorted(vals)
    best_so_far = math.factorial(abs(m) % 9)
    max_value = math.gcd(m, n)
    best_so_far += sum(lst)
cnt = go(acc)
